"""Compile ``skill.md`` into :class:`~rasa.mantle.skills.skill.Skill`.

Compilation is split into small stages:

1. Frontmatter metadata
2. ``tool_constraints`` / ``import_tools`` → skill-level gated tools
3. Document-ordered ``body``: ``ProseBlock`` interleaved with ``OrderedBlock``
4. ``:::ordered_block`` YAML → :class:`~rasa.mantle.skills.skill.OrderedBlock`
   via :func:`~rasa.mantle.skills.catalog.parse_ordered_block_dict`. ``routable``
   is engine-owned: ``False`` for hybrid skills (prose + blocks), ``True`` for
   fully controlled (blocks only). Authors must not set it.
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import Any, Dict, NamedTuple

