_INVALID_TOOL_CONSTRAINTS_CODE = "skill.markdown.invalid_tool_constraints"
_INVALID_UTTER_CODE = "skill.markdown.invalid_utter"
_INVALID_ORDERED_BLOCK_CODE = "skill.markdown.invalid_ordered_block"
_INVALID_BLOCK_REFERENCE_CODE = "skill.markdown.invalid_block_reference"
_ORDERED_BLOCK_ROUTABLE_FORBIDDEN_CODE = (
    "skill.markdown.ordered_block_routable_forbidden"
)
_INVALID_FRONTMATTER_DELIMITER_CODE = "skill.markdown.invalid_frontmatter_delimiter"
_COMPLETE_WHEN_MAPPING_REQUIRED_CODE = "skill.complete_when.mapping_required"
_COMPLETE_WHEN_INVALID_CODE = "skill.complete_when.invalid"
_COMPLETE_WHEN_REQUIRES_PROSE_CODE = "skill.complete_when.requires_prose"

_ORDERED_BLOCK_PATTERN = re.compile(
    r":::ordered_block(?:\s+id=(?P<block_id>[\w-]+))?"
    r"\s*\n(?P<block_body>.*?)^:::\s*$",
    re.DOTALL | re.MULTILINE,
)

# One-segment tokens; extra path segments are incomplete lookalikes.
_PROSE_SKILL_REF_PATTERN = re.compile(r"(?<![\w])@skill\.([\w-]+)(?![\w-])(?!\.[\w-])")
_PROSE_SKILL_LOOKALIKE_PATTERN = re.compile(r"(?<![\w])@skill(?:\.[\w-]+)*(?![\w-])")
_PROSE_BLOCK_REF_PATTERN = re.compile(r"(?<![\w])@block\.([\w-]+)(?![\w-])(?!\.[\w-])")
_PROSE_BLOCK_LOOKALIKE_PATTERN = re.compile(r"(?<![\w])@block(?:\.[\w-]+)*(?![\w-])")


def _split_frontmatter_sections(content: str) -> tuple[str, str]:
    """Split stripped ``skill.md`` text into YAML frontmatter and markdown body.

    Scans line-by-line for opening/closing ``---`` delimiters (linear time).
    """
    lines = content.splitlines()
    if not lines or lines[0].strip() != "---":
        raise ValidationError(
            code=_INVALID_FRONTMATTER_DELIMITER_CODE,
            event_info="skill.md must start with YAML frontmatter (--- ... ---)",
        )

    closing_idx = next(
        (idx for idx in range(1, len(lines)) if lines[idx].strip() == "---"),
        None,
    )
    if closing_idx is None:
        raise ValidationError(
            code=_INVALID_FRONTMATTER_DELIMITER_CODE,
            event_info="skill.md must start with YAML frontmatter (--- ... ---)",
        )

    frontmatter_raw = "\n".join(lines[1:closing_idx])
    body = "\n".join(lines[closing_idx + 1 :])
    return frontmatter_raw, body


def collect_prose_skill_references(prose: str) -> list[str]:
    """Collect unique ``@skill.<skill_id>`` tokens from markdown prose.

    The token after ``@skill.`` must be the skill directory / catalog id
    (e.g. ``card_disambiguation``), not the human-readable ``name`` from
    frontmatter.
    """
    seen: set[str] = set()
    referenced: list[str] = []
    for match in _PROSE_SKILL_REF_PATTERN.finditer(prose):
        skill_id = match.group(1)
        if skill_id in seen:
            continue
        seen.add(skill_id)
        referenced.append(skill_id)
    return referenced


def collect_incomplete_prose_at_tokens(prose: str) -> list[str]:
    """Collect unique incomplete ``@skill`` / ``@block`` / ``@tool`` lookalikes.

    Returns token strings (e.g. ``@skill``, ``@tool.foo.bar``) in first-seen
    order. Well-formed one-segment tokens are excluded.
    """
    seen: set[str] = set()
    incomplete: list[str] = []
    positioned: list[tuple[int, str]] = []
    for complete_pattern, lookalike_pattern in (
        (_PROSE_SKILL_REF_PATTERN, _PROSE_SKILL_LOOKALIKE_PATTERN),
        (_PROSE_BLOCK_REF_PATTERN, _PROSE_BLOCK_LOOKALIKE_PATTERN),
        (_PROSE_TOOL_REF_PATTERN, _PROSE_TOOL_LOOKALIKE_PATTERN),
    ):
        for match in lookalike_pattern.finditer(prose):
            token = match.group(0)
            if complete_pattern.fullmatch(token):
                continue
            positioned.append((match.start(), token))
    for _, token in sorted(positioned, key=lambda item: item[0]):
        if token in seen:
            continue
        seen.add(token)
        incomplete.append(token)
    return incomplete


def collect_prose_block_references(prose: str) -> list[str]:
    """Collect unique ``@block.<block_id>`` tokens from markdown prose.

    The token after ``@block.`` must be the ordered-block id from
    ``:::ordered_block id=<block_id>`` (e.g. ``main``), not the compiled
    target id (``{skill_id}__{block_id}``).
    """
    seen: set[str] = set()
    referenced: list[str] = []
    for match in _PROSE_BLOCK_REF_PATTERN.finditer(prose):
        block_id = match.group(1)
        if block_id in seen:
            continue
        seen.add(block_id)
        referenced.append(block_id)
    return referenced


def _prose_block_target_ids(
    skill_id: str, prose: str, local_block_ids: set[str]
) -> list[str]:
    """Normalize prose ``@block`` references to compiled target IDs."""
    target_ids: list[str] = []
    for block_id in collect_prose_block_references(prose):
        if block_id not in local_block_ids:
            raise ValidationError(
                code=_INVALID_BLOCK_REFERENCE_CODE,
                event_info=(
                    f"Unknown ordered block {block_id!r} on skill {skill_id!r}; "
                    "@block. must reference a block id defined in this skill."
                ),
            )
        target_ids.append(format_ordered_block_target_id(skill_id, block_id))
    return target_ids


def split_skill_markdown(content: str) -> tuple[dict[str, Any], str]:
    """Split ``skill.md`` text into YAML frontmatter and markdown body.

    Args:
        content: Full ``skill.md`` file contents.

    Returns:
        A ``(frontmatter, body)`` pair.  *frontmatter* is the parsed YAML mapping;
        *body* is the markdown text after the closing ``---`` (stripped).

    Raises:
        ValueError: When frontmatter delimiters are missing.
        ValidationError: When parsed frontmatter is not a YAML mapping.
    """
    frontmatter_raw, body = _split_frontmatter_sections(content.strip())
    frontmatter = yaml.safe_load(frontmatter_raw) or {}
    if not isinstance(frontmatter, dict):
        raise ValidationError(
            code="skill.markdown.invalid_frontmatter",
            event_info="skill.md frontmatter must be a YAML mapping.",
        )
    return frontmatter, body.strip()


def _parse_requires_confirmation(
    raw: Any, tool_name: str
) -> RequiresConfirmation | None:
    """Parse nested ``requires_confirmation`` settings.

    ``enabled`` (bool, default ``False``) turns the confirmation gate on.
    Optional ``utter_for_confirmation`` / ``utter_on_user_denial`` are names of
    responses in ``responses.yml``; when omitted, the LLM handles that response.
    Unknown nested keys and non-mapping values are rejected.

    Returns ``None`` when confirmation is not enabled so
    ``GatedTool.requires_confirmation`` stays unset (no pause at runtime).
    """
    if not isinstance(raw, dict):
        raise ValidationError(
            code=_INVALID_TOOL_CONSTRAINTS_CODE,
            event_info=(
                f"Constraint option '{REQUIRES_CONFIRMATION_FIELD}' for tool "
                f"'{tool_name}' must be a mapping."
            ),
        )

    unknown_keys = sorted(set(raw) - set(REQUIRES_CONFIRMATION_FIELDS))
    if unknown_keys:
        raise ValidationError(
            code=_INVALID_TOOL_CONSTRAINTS_CODE,
            event_info=(
                f"Unknown key(s) in {REQUIRES_CONFIRMATION_FIELD} for tool "
                f"'{tool_name}': "
                f"{', '.join(repr(key) for key in unknown_keys)}. "
                f"Allowed keys: {', '.join(REQUIRES_CONFIRMATION_FIELDS)}."
            ),
        )

    enabled = False
    if ENABLED_FIELD in raw and raw[ENABLED_FIELD] is not None:
        enabled_value = raw[ENABLED_FIELD]
        if not isinstance(enabled_value, bool):
            raise ValidationError(
                code=_INVALID_TOOL_CONSTRAINTS_CODE,
                event_info=(
                    f"{REQUIRES_CONFIRMATION_FIELD}.{ENABLED_FIELD} for tool "
                    f"'{tool_name}' must be a boolean."
                ),
            )
        enabled = enabled_value

    if not enabled:
        return None

    response_names: dict[str, str] = {}
    for field_name in (
        UTTER_FOR_CONFIRMATION_FIELD,
        UTTER_ON_USER_DENIAL_FIELD,
    ):
        if field_name not in raw or raw[field_name] is None:
            continue
        value = raw[field_name]
        if not isinstance(value, str):
            raise ValidationError(
                code=_INVALID_TOOL_CONSTRAINTS_CODE,
                event_info=(
                    f"{REQUIRES_CONFIRMATION_FIELD}.{field_name} for tool "
                    f"'{tool_name}' must be a string."
                ),
            )
        response_names[field_name] = value

    return RequiresConfirmation(enabled=True, **response_names)


def _parse_tool_constraint_entry(entry: Any) -> GatedTool:
    """Parse one ``tool_constraints`` list entry into a :class:`GatedTool`.

    Each entry is a single-key mapping::

        - process_card_replacement:
            requires: session.card_replace.shipping_type
            requires_confirmation:
              enabled: true
              utter_for_confirmation: utter_ask_replacement_confirmation
              utter_on_user_denial: utter_replacement_cancelled
            on_success: utter_replacement_disclaimer
            on_failure: utter_replacement_failed
    """
    if not isinstance(entry, dict) or len(entry) != 1:
        raise ValidationError(
            code=_INVALID_TOOL_CONSTRAINTS_CODE,
            event_info=(
                "Each tool_constraints entry must be a single-key mapping from "
                "tool name to its constraint options."
            ),
        )

    tool_name, config = next(iter(entry.items()))
    if not isinstance(tool_name, str) or not tool_name:
        raise ValidationError(
            code=_INVALID_TOOL_CONSTRAINTS_CODE,
            event_info="Each tool_constraints entry must use the tool name as its key.",
        )

    # Bare ``- tool_name:`` means unconstrained.
    if config is None:
        config = {}
    if not isinstance(config, dict):
        raise ValidationError(
            code=_INVALID_TOOL_CONSTRAINTS_CODE,
            event_info=f"Constraint options for tool '{tool_name}' must be a mapping.",
        )

    unknown_keys = sorted(set(config) - set(TOOL_CONSTRAINT_FIELDS))
    if unknown_keys:
        raise ValidationError(
            code=_INVALID_TOOL_CONSTRAINTS_CODE,
            event_info=(
                f"Unknown key(s) in tool_constraints for tool '{tool_name}': "
                f"{', '.join(repr(key) for key in unknown_keys)}. "
                f"Allowed keys: {', '.join(TOOL_CONSTRAINT_FIELDS)}."
            ),
        )

    optional_strings: dict[str, str] = {}
    for field_name in TOOL_CONSTRAINT_STRING_FIELDS:
        if field_name not in config or config[field_name] is None:
            continue
        value = config[field_name]
        if not isinstance(value, str):
            raise ValidationError(
                code=_INVALID_TOOL_CONSTRAINTS_CODE,
                event_info=(
                    f"Constraint option '{field_name}' for tool '{tool_name}' "
                    "must be a string when present."
                ),
            )
        optional_strings[field_name] = value

    requires_confirmation: RequiresConfirmation | None = None
    # Check key presence so a bare ``requires_confirmation:`` reaches the
    # parser and fails validation instead of silently disabling the gate.
    if REQUIRES_CONFIRMATION_FIELD in config:
        requires_confirmation = _parse_requires_confirmation(
            config[REQUIRES_CONFIRMATION_FIELD], tool_name
        )

    return GatedTool(
        name=tool_name,
        requires_confirmation=requires_confirmation,
        **optional_strings,
    )


def _compile_tool_constraints(raw: Any) -> list[GatedTool]:
    """Compile ``tool_constraints`` frontmatter into gated tool entries."""
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise ValidationError(
            code=_INVALID_TOOL_CONSTRAINTS_CODE,
            event_info="tool_constraints must be a YAML list.",
        )
    return [_parse_tool_constraint_entry(entry) for entry in raw]


def _compile_import_tools(raw: Any) -> list[GatedTool]:
    """Compile local and MCP imports into bare-name tool gate entries."""
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise ValidationError(
            code="skill.markdown.invalid_import_tools",
            event_info="import_tools must be a YAML list of tool name strings.",
        )
    tools: list[GatedTool] = []
    for entry in raw:
        if not isinstance(entry, str):
            raise ValidationError(
                code="skill.markdown.invalid_import_tools",
                event_info=(
                    "Each import_tools entry must be a shared tool name string; "
                    f"got {type(entry).__name__}."
                ),
            )
        from rasa.mantle.tools.mcp_import_spec import get_bare_tool_name

        try:
            tool_name = get_bare_tool_name(entry)
        except ValueError as exc:
            raise ValidationError(
                code="skill.markdown.invalid_import_tools",
                event_info=str(exc),
            ) from exc
        tools.append(GatedTool(name=tool_name))
    return tools


def _merge_skill_tools(
    tool_constraints: list[GatedTool],
    import_tools: list[GatedTool],
) -> list[GatedTool]:
    """Merge constrained and imported tools, with constraints taking precedence."""
    by_name: dict[str, GatedTool] = {tool.name: tool for tool in import_tools}
    by_name.update({tool.name: tool for tool in tool_constraints})
    constraint_names = {tool.name for tool in tool_constraints}
    ordered_names = [tool.name for tool in tool_constraints]
    ordered_names.extend(
        tool.name for tool in import_tools if tool.name not in constraint_names
    )
    return [by_name[name] for name in ordered_names]


def _compile_knowledge_answering_instructions(raw: Any) -> str | None:
    """Compile and validate the ``knowledge_answering.instructions`` frontmatter.

    ``knowledge_answering``, when present, must be a mapping whose
    ``instructions`` is a string. Returns ``None`` when the skill authors none.
    Validation lives here so every caller of :func:`compile_skill_logic` enforces
    the same contract.
    """
    if raw is None:
        return None
    if not isinstance(raw, dict):
        raise ValidationError(
            code="skill.markdown.invalid_knowledge_answering",
            event_info=(
                "knowledge_answering must be a YAML mapping when present in skill.md."
            ),
        )
    instructions = raw.get("instructions")
    if instructions is not None and not isinstance(instructions, str):
        raise ValidationError(
            code="skill.markdown.invalid_knowledge_answering",
            event_info=(
                "knowledge_answering.instructions must be a string when present."
            ),
        )
    return instructions


def _parse_utter_when_condition(raw: Any, response_name: str) -> Condition:
    """Parse an ``utter:`` ``when:`` condition expression.

    Uses the same expression syntax as ``requires`` / ``complete_when`` and prose
    ``if:`` — memory is referenced as ``session.<namespace>.<entry>``.
    """
    if not isinstance(raw, str) or not raw.strip():
        raise ValidationError(
            code=_INVALID_UTTER_CODE,
            event_info=(
                f"utter trigger '{response_name}' when: must be a non-empty "
                "condition expression string, e.g. "
                "'session.<skill_id>.<entry> == \"value\"'."
            ),
        )

    condition = raw.strip()
    try:
        validate_condition_syntax(condition)
    except ConditionEvaluationError as exc:
        raise ValidationError(
            code=_INVALID_UTTER_CODE,
            event_info=(
                f"utter trigger '{response_name}' has an invalid when: condition "
                f"{condition!r}: {exc}"
            ),
        ) from exc
    return condition


def _parse_utter_on_activate(config: dict[Any, Any], response_name: str) -> bool:
    """Return whether *config* enables ``on: activate`` for an utter trigger.

    Unquoted YAML 1.1 ``on`` loads as boolean ``True``
    (``{True: "activate"}`` / ``{True: None}`` for bare ``on:``), including when
    ``when`` is also set.
    """
    if UTTER_ON_FIELD not in config and True not in config:
        return False
    on_value = config[UTTER_ON_FIELD] if UTTER_ON_FIELD in config else config[True]
    if on_value is None or on_value == UTTER_ON_ACTIVATE_VALUE:
        return True
    raise ValidationError(
        code=_INVALID_UTTER_CODE,
        event_info=(
            f"utter trigger '{response_name}' has unsupported "
            f"{UTTER_ON_FIELD}: value {on_value!r}; use "
            f"{UTTER_ON_FIELD}: {UTTER_ON_ACTIVATE_VALUE}."
        ),
    )


def _parse_utter_entry(entry: Any) -> VerbatimTrigger:
    """Parse one ``utter:`` list entry into a :class:`VerbatimTrigger`."""
    response_name: str | None = None
    config: Any = None
    if isinstance(entry, dict) and len(entry) == 1:
        response_name, config = next(iter(entry.items()))
        if config is None:
            config = {}

    if (
        not isinstance(response_name, str)
        or not response_name
        or not isinstance(config, dict)
    ):
        raise ValidationError(
            code=_INVALID_UTTER_CODE,
            event_info=(
                "Each utter entry must be a single-key mapping from response "
                "name to its trigger options."
            ),
        )

    on_activate = _parse_utter_on_activate(config, response_name)
    when_raw = config.get(UTTER_WHEN_FIELD)
    when_condition = (
        _parse_utter_when_condition(when_raw, response_name)
        if when_raw is not None
        else None
    )

    if not on_activate and when_condition is None:
        raise ValidationError(
            code=_INVALID_UTTER_CODE,
            event_info=(
                f"utter trigger '{response_name}' must set "
                f"'{UTTER_ON_FIELD}: {UTTER_ON_ACTIVATE_VALUE}' or "
                f"'{UTTER_WHEN_FIELD}:'."
            ),
        )

    return VerbatimTrigger(
        response_name=response_name,
        on_activate=on_activate,
        when_condition=when_condition,
    )


def _compile_utter_triggers(raw: Any) -> list[VerbatimTrigger]:
    """Compile ``utter`` frontmatter into verbatim trigger entries."""
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise ValidationError(
            code=_INVALID_UTTER_CODE,
            event_info="utter must be a YAML list.",
        )

    triggers: list[VerbatimTrigger] = []
    seen_names: set[str] = set()

    for entry in raw:
        trigger = _parse_utter_entry(entry)
        if trigger.response_name in seen_names:
            raise ValidationError(
                code=_INVALID_UTTER_CODE,
                event_info=(
                    f"Duplicate utter trigger response name "
                    f"'{trigger.response_name}'."
                ),
            )
        seen_names.add(trigger.response_name)
        triggers.append(trigger)
    return triggers


class _FrontmatterBehavior(NamedTuple):
    """Frontmatter behavioural fields compiled for :func:`compile_skill`."""

    tools: list[GatedTool]
    import_tool_names: frozenset[str]
    tool_constraint_names: frozenset[str]
    verbatim_triggers: list[VerbatimTrigger]
    knowledge_answering_instructions: str | None


def compile_skill_logic(frontmatter: dict[str, Any]) -> _FrontmatterBehavior:
    """Compile behavioural frontmatter fields (tools, imports, utter triggers)."""
    return _compile_parsed_skill_logic(parse_skill_frontmatter(frontmatter))


def _compile_parsed_skill_logic(parsed: SkillFrontmatter) -> _FrontmatterBehavior:
    """Compile tools, imports, and utter triggers from a validated model."""
    raw_import_tools = list(parsed.import_tools)
    tool_constraints = _compile_tool_constraints(
        [entry.model_dump(exclude_none=True) for entry in parsed.tool_constraints]
    )
    import_tools = _compile_import_tools(raw_import_tools)
    knowledge_answering = (
        parsed.knowledge_answering.model_dump(exclude_none=True)
        if parsed.knowledge_answering is not None
        else None
    )
    return _FrontmatterBehavior(
        tools=_merge_skill_tools(tool_constraints, import_tools),
        import_tool_names=frozenset(raw_import_tools),
        tool_constraint_names=frozenset(tool.name for tool in tool_constraints),
        verbatim_triggers=_compile_utter_triggers(
            [entry.model_dump(exclude_none=True) for entry in parsed.utter]
        ),
        knowledge_answering_instructions=_compile_knowledge_answering_instructions(
            knowledge_answering
        ),
    )


def _body_has_ordered_blocks(body: str) -> bool:
    return bool(_ORDERED_BLOCK_PATTERN.search(body))


def _compile_ordered_block(block_id: str, raw: dict[str, Any]) -> OrderedBlock:
    """Compile one ordered block into an :class:`OrderedBlock`.

    *raw* must already include the engine-owned ``routable`` value (callers
    reject author ``routable`` and inject the flag before calling this).
    """
    return parse_ordered_block_dict(block_id, raw)


def _parse_ordered_blocks(body: str) -> list[tuple[str, dict[str, Any]]]:
    """Parse ``:::ordered_block`` sections into ``(block_id, yaml_body)`` pairs."""
    blocks: list[tuple[str, dict[str, Any]]] = []
    seen_ids: set[str] = set()

    for match in _ORDERED_BLOCK_PATTERN.finditer(body):
        block_id = match.group("block_id")
        if not block_id:
            raise ValidationError(
                code=_INVALID_ORDERED_BLOCK_CODE,
                event_info=(
                    "Each :::ordered_block section must declare an id attribute "
                    "(e.g. :::ordered_block id=verify)."
                ),
            )

        content = (match.group("block_body") or "").strip()
        raw = yaml.safe_load(content) if content else {}
        if raw is None:
            raw = {}
        if not isinstance(raw, dict):
            raise ValidationError(
                code=_INVALID_ORDERED_BLOCK_CODE,
                event_info=(f"Ordered block '{block_id}' body must be a YAML mapping."),
            )

        if block_id in seen_ids:
            raise ValidationError(
                code=_INVALID_ORDERED_BLOCK_CODE,
                event_info=f"Duplicate ordered block id '{block_id}'.",
            )
        seen_ids.add(block_id)
        blocks.append((block_id, raw))

    return blocks


def _merge_ordered_block_tools(
    blocks: list[OrderedBlock],
    *,
    tools: list[GatedTool],
    tool_constraint_names: frozenset[str],
) -> tuple[list[GatedTool], frozenset[str]]:
    """Fold ordered-block ``tools`` into skill-level constraint metadata."""
    flow_tools: list[GatedTool] = []
    for block in blocks:
        flow_tools.extend(block.tools)
    if not flow_tools:
        return tools, tool_constraint_names

    constraint_names = set(tool_constraint_names)
    constraint_names.update(tool.name for tool in flow_tools)

    tools_by_name = {tool.name: tool for tool in tools}
    for tool in flow_tools:
        tools_by_name.setdefault(tool.name, tool)

    ordered_names = [tool.name for tool in tools]
    ordered_names.extend(
        tool.name for tool in flow_tools if tool.name not in ordered_names
    )
    merged_tools = [tools_by_name[name] for name in ordered_names]
    return merged_tools, frozenset(constraint_names)


def _parse_skill_body(body: str) -> list[SkillBodyBlock]:
    """Parse Markdown into document-ordered skill body blocks."""
    blocks: list[SkillBodyBlock] = []
    cursor = 0

    def _append_prose(chunk: str) -> None:
        segments = parse_prose_instruction_segments(chunk)
        if segments:
            blocks.append(ProseBlock(segments=segments))

    for match in _ORDERED_BLOCK_PATTERN.finditer(body):
        _append_prose(body[cursor : match.start()])
        block_id = match.group("block_id")
        if block_id:
            blocks.append(OrderedBlock(block_id=block_id))
        cursor = match.end()
    _append_prose(body[cursor:])

    return blocks


def _prose_segments(body: list[SkillBodyBlock]) -> list[ProseSegment]:
    """Flatten prose segments from a document-ordered skill body."""
    return [
        segment
        for block in body
        if isinstance(block, ProseBlock)
        for segment in block.segments
    ]


def _replace_ordered_blocks(
    body: list[SkillBodyBlock],
    ordered_blocks_by_id: dict[str, OrderedBlock],
) -> list[SkillBodyBlock]:
    """Replace parsed block placeholders with their compiled values."""
    return [
        ordered_blocks_by_id[block.block_id]
        if isinstance(block, OrderedBlock)
        else block
        for block in body
    ]


class _CompiledSkillParts(NamedTuple):
    """Intermediate compile artifacts for :func:`compile_skill`."""

    body: list[SkillBodyBlock]
    prose: str
    ordered_blocks: list[OrderedBlock]
    tools: list[GatedTool]
    import_tool_names: frozenset[str]
    tool_constraint_names: frozenset[str]
    verbatim_triggers: list[VerbatimTrigger]
    complete_when: CompleteWhenSpec | None
    knowledge_answering_instructions: str | None


def _compile_skill_parts(
    frontmatter: Dict[str, Any],
    body: str,
    *,
    skill_id: str,
) -> _CompiledSkillParts:
    """Shared parse/compile path for ``compile_skill``."""
    parsed_frontmatter = parse_skill_frontmatter(frontmatter)
    parsed_body = _parse_skill_body(body)
    segments = _prose_segments(parsed_body)
    prose = "\n\n".join(segment.text for segment in segments)
    complete_when = _compile_complete_when_spec(
        None
        if parsed_frontmatter.complete_when is None
        else parsed_frontmatter.complete_when.model_dump(exclude_none=True)
    )
    if complete_when is not None and not segments:
        raise ValidationError(
            code=_COMPLETE_WHEN_REQUIRES_PROSE_CODE,
            event_info=(
                "complete_when requires prose instructions (autonomous or "
                "hybrid skills). Fully controlled ordered-block-only skills "
                "complete via block END without this gate — remove skill-level "
                "complete_when, or add prose and exit via complete."
            ),
        )
    if not segments and not _body_has_ordered_blocks(body):
        raise ValidationError(
            code="skill.markdown.missing_instructions",
            event_info="skill.md must include prose instructions or ordered blocks.",
        )

    logic = _compile_parsed_skill_logic(parsed_frontmatter)
    ordered_block_routable = not segments
    ordered_blocks: list[OrderedBlock] = []
    for block_id, block_raw in _parse_ordered_blocks(body):
        if "routable" in block_raw:
            raise ValidationError(
                code=_ORDERED_BLOCK_ROUTABLE_FORBIDDEN_CODE,
                event_info=(
                    f"Ordered block '{block_id}' must not set 'routable'. "
                    "The engine sets routable for ordered blocks "
                    "(false when the skill has prose + ordered blocks, "
                    "true for fully controlled block-only skills). "
                    "Remove the routable key from skill.md."
                ),
            )
        block_raw["routable"] = ordered_block_routable
        ordered_blocks.append(_compile_ordered_block(block_id, block_raw))

    ordered_blocks = resolve_ordered_block_step_targets(
        skill_id, ordered_blocks, has_prose_entry=bool(segments)
    )
    ordered_blocks_by_id = {block.block_id: block for block in ordered_blocks}
    tools, tool_constraint_names = _merge_ordered_block_tools(
        ordered_blocks,
        tools=list(logic.tools),
        tool_constraint_names=logic.tool_constraint_names,
    )
    return _CompiledSkillParts(
        body=_replace_ordered_blocks(parsed_body, ordered_blocks_by_id),
        prose=prose,
        ordered_blocks=ordered_blocks,
        tools=tools,
        import_tool_names=logic.import_tool_names,
        tool_constraint_names=tool_constraint_names,
        verbatim_triggers=list(logic.verbatim_triggers),
        complete_when=complete_when,
        knowledge_answering_instructions=logic.knowledge_answering_instructions,
    )


def _compile_complete_when_string_list(
    raw: Any,
    *,
    field_name: str,
) -> tuple[str, ...]:
    """Normalize a frontmatter list of non-empty strings."""
    if raw is None:
        return ()
    if not isinstance(raw, list):
        raise ValidationError(
            code=_COMPLETE_WHEN_INVALID_CODE,
            event_info=(
                f"complete_when.{field_name} must be a list of strings, "
                f"got {type(raw).__name__}."
            ),
        )
    values: list[str] = []
    seen: set[str] = set()
    for index, item in enumerate(raw):
        if not isinstance(item, str) or not item.strip():
            raise ValidationError(
                code=_COMPLETE_WHEN_INVALID_CODE,
                event_info=(
                    f"complete_when.{field_name}[{index}] must be a non-empty string."
                ),
            )
        value = item.strip()
        if value in seen:
            raise ValidationError(
                code=_COMPLETE_WHEN_INVALID_CODE,
                event_info=(
                    f"complete_when.{field_name} contains duplicate entry {value!r}."
                ),
            )
        seen.add(value)
        values.append(value)
    return tuple(values)


def _compile_complete_when_condition(raw: Any) -> str | None:
    """Normalize optional skill-level ``complete_when.condition`` string."""
    if raw is None:
        return None
    if not isinstance(raw, str) or not raw.strip():
        raise ValidationError(
            code=_COMPLETE_WHEN_INVALID_CODE,
            event_info=(
                "complete_when.condition must be a non-empty condition string, "
                f"got {type(raw).__name__}."
            ),
        )
    condition = raw.strip()
    try:
        validate_condition_syntax(condition)
    except ConditionEvaluationError as exc:
        raise ValidationError(
            code=_COMPLETE_WHEN_INVALID_CODE,
            event_info=(
                f"complete_when.condition has an invalid expression "
                f"{condition!r}: {exc}"
            ),
        ) from exc
    return condition


def _compile_complete_when_spec(raw: Any) -> CompleteWhenSpec | None:
    """Compile skill-level ``complete_when`` (mapping only; bare string rejected)."""
    if raw is None:
        return None
    if isinstance(raw, str):
        raise ValidationError(
            code=_COMPLETE_WHEN_MAPPING_REQUIRED_CODE,
            event_info=(
                "complete_when must be a mapping with 'condition' and/or "
                "'criteria' (bare strings are not allowed)."
            ),
        )
    if not isinstance(raw, dict):
        raise ValidationError(
            code=_COMPLETE_WHEN_INVALID_CODE,
            event_info=(
                "complete_when must be a mapping with 'condition' and/or "
                f"'criteria', got {type(raw).__name__}."
            ),
        )

    allowed_keys = {"condition", "criteria"}
    unknown = sorted(str(key) for key in set(raw) - allowed_keys)
    if unknown:
        raise ValidationError(
            code=_COMPLETE_WHEN_INVALID_CODE,
            event_info=(
                "complete_when only allows 'condition' and 'criteria'; "
                f"unknown keys: {', '.join(unknown)}."
            ),
        )

    condition = _compile_complete_when_condition(raw.get("condition"))
    criteria = _compile_complete_when_string_list(
        raw.get("criteria"), field_name="criteria"
    )

    try:
        return CompleteWhenSpec(condition=condition, criteria=criteria)
    except ValueError as error:
        raise ValidationError(
            code=_COMPLETE_WHEN_INVALID_CODE,
            event_info=str(error),
        ) from error


def compile_skill(
    frontmatter: Dict[str, Any],
    body: str,
    *,
    skill_id: str,
) -> Skill:
    """Compile frontmatter and Markdown body into a :class:`Skill` with ``body``."""
    parsed = parse_skill_frontmatter(frontmatter)
    parts = _compile_skill_parts(frontmatter, body, skill_id=skill_id)
    skills, blocks = partition_call_link_targets_from_ordered_blocks(
        skill_id, parts.ordered_blocks
    )
    return Skill(
        id=skill_id,
        name=parsed.name,
        description=parsed.description,
        body=parts.body,
        tools=list(parts.tools),
        import_tool_names=parts.import_tool_names,
        tool_constraint_names=parts.tool_constraint_names,
        verbatim_triggers=list(parts.verbatim_triggers),
        complete_when=parts.complete_when,
        knowledge_answering_instructions=parts.knowledge_answering_instructions,
        memory=SkillMemoryContract(),
        precondition=parsed.precondition,
        disabled=parsed.disabled,
        always_include_in_prompt=parsed.always_include_in_prompt,
        hidden=parsed.hidden,
        is_default=parsed.routing.is_default,
        engine_managed=parsed.routing.engine_managed,
        referenced_skills=merge_referenced_ids(
            skills,
            collect_prose_skill_references(parts.prose),
        ),
        referenced_blocks=merge_referenced_ids(
            blocks,
            _prose_block_target_ids(
                skill_id,
                parts.prose,
                {block.block_id for block in parts.ordered_blocks},
            ),
        ),
    )


def compile_markdown_skill(path: Path) -> Skill:
    """Compile a ``skill.md`` file into a :class:`~rasa.mantle.skills.skill.Skill`.

    The skill id is always the parent directory name.
    """
    content = path.read_text(encoding="utf-8")
    frontmatter, body = split_skill_markdown(content)
    return compile_skill(frontmatter, body, skill_id=path.parent.name)
